<?php
declare(strict_types=1);
namespace Architex\Tests\Integration\Http;
use Architex\Http\AuthenticationKernelFactory;use Architex\Http\Request;use Architex\Platform\Identity\Identifier;use Architex\Platform\Identity\PasswordResetNotifier;use Architex\Platform\Identity\RegistrationNotifier;use Architex\Platform\Identity\SessionService;use Architex\Tests\Support\MariaDbTestCase;
final class RegulatoryCaseHttpTest extends MariaDbTestCase
{
 public function testAuthenticatedEnvironmentalDeterminationPersists():void{[$o,$u,$p]=$this->seed();$n=new class implements RegistrationNotifier,PasswordResetNotifier{public function isAvailable():bool{return false;}public function send(string$email,string$token,string$expiresAt):void{}};$k=(new AuthenticationKernelFactory($this->pdo,$n,$n))->create();$session=(new SessionService($this->pdo))->rotate($u);$h=['Cookie'=>'architex_session='.$session->token,'X-Organisation-Id'=>$o,'X-CSRF-Token'=>$session->csrfToken];$payload=['caseNumber'=>'ENV-HTTP-1','caseType'=>'environmental','title'=>'HTTP screening','authorityName'=>'Competent authority','responsibleRole'=>'environmental_practitioner','sourceBasis'=>[['title'=>'DFFE EGIS','url'=>'https://www.dffe.gov.za/egis','retrievedAt'=>'2026-08-28']]];$no=$h;unset($no['X-CSRF-Token']);self::assertSame(419,$k->handle($this->json('POST',"/api/v1/projects/$p/regulatory-cases",$no,$payload))->status());$created=$k->handle($this->json('POST',"/api/v1/projects/$p/regulatory-cases",$h,$payload));self::assertSame(201,$created->status(),$created->body());$case=$created->json()['data'];foreach([['screening_report','Screening report','SCREEN-HTTP'],['site_sensitivity_verification','Site verification','SSV-HTTP']]as$i=>$item){$response=$k->handle($this->json('POST',"/api/v1/regulatory-cases/{$case['id']}/evidence",$h,['expectedVersion'=>$i+1,'evidenceType'=>$item[0],'title'=>$item[1],'status'=>'complete','externalReference'=>$item[2],'sourceUrl'=>'https://example.test/evidence/'.$item[2],'observedAt'=>'2026-08-28','payload'=>['humanEntered'=>true]]));self::assertSame(201,$response->status(),$response->body());}$determined=$k->handle($this->json('POST',"/api/v1/regulatory-cases/{$case['id']}/determine",$h,['expectedVersion'=>3,'humanConfirmed'=>true,'professionalRole'=>'environmental_practitioner','route'=>'basic_assessment','reason'=>'Exact source evidence reviewed by responsible practitioner.','externalReference'=>'ROUTE-HTTP-1']));self::assertSame(200,$determined->status(),$determined->body());self::assertFalse($determined->json()['data']['authorityDecisionClaimed']);self::assertMatchesRegularExpression('/\A[a-f0-9]{64}\z/',$determined->json()['data']['snapshotSha256']);$list=$k->handle(Request::json('GET',"/api/v1/projects/$p/regulatory-cases?type=environmental",$h));self::assertSame(200,$list->status());self::assertCount(1,$list->json()['data']);$export=$k->handle(Request::json('GET',"/api/v1/regulatory-cases/{$case['id']}/exports/json",$h));self::assertSame(200,$export->status());self::assertSame('application/json',$export->header('Content-Type'));self::assertSame(hash('sha256',$export->body()),$export->header('X-Content-Sha256'));}
 /** @return array{string,string,string} */private function seed():array{$o=Identifier::generate();$u=Identifier::generate();$reviewer=Identifier::generate();$p=Identifier::generate();$this->pdo->prepare("INSERT INTO users(id,email,password_hash,status,email_verified_at) VALUES(UNHEX(:id),'reg-http@example.test','hash','active',UTC_TIMESTAMP(6)),(UNHEX(:reviewer),'reg-http-reviewer@example.test','hash','active',UTC_TIMESTAMP(6))")->execute(['id'=>$u,'reviewer'=>$reviewer]);$this->pdo->prepare("INSERT INTO organisations(id,name,slug,status) VALUES(UNHEX(:id),'Reg HTTP',:slug,'active')")->execute(['id'=>$o,'slug'=>'reg-http-'.substr($o,0,8)]);$this->pdo->prepare("INSERT INTO organisation_memberships(id,organisation_id,user_id,role,status) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:u),'owner','active')")->execute(['id'=>Identifier::generate(),'o'=>$o,'u'=>$u]);$this->pdo->prepare("INSERT INTO professional_profiles(id,organisation_id,user_id,display_name,profession,bio,service_areas,directory_visible) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:u),'HTTP Environmental Practitioner','environmental_practitioner','Test profile',JSON_ARRAY('Gauteng'),0)")->execute(['id'=>Identifier::generate(),'o'=>$o,'u'=>$u]);$this->pdo->prepare("INSERT INTO verification_records(id,organisation_id,user_id,kind,grade,registration_body,registration_number,popia_consent_at,processing_purpose,retention_until,reviewed_by,reviewed_at) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:u),'professional_registration','manually_reviewed','EAPASA','TEST-ENV-01',UTC_TIMESTAMP(6),'Regulatory determination test',DATE_ADD(UTC_DATE(),INTERVAL 1 YEAR),UNHEX(:reviewer),UTC_TIMESTAMP(6))")->execute(['id'=>Identifier::generate(),'o'=>$o,'u'=>$u,'reviewer'=>$reviewer]);$this->pdo->prepare("INSERT INTO projects(id,organisation_id,project_code,project_name,client_name,municipality,property_reference,property_use,land_use_notes,lead_professional_role,current_phase,created_by) VALUES(UNHEX(:id),UNHEX(:o),'REG-HTTP','Regulatory HTTP','Client','Tshwane','Erf 61','Mixed use','', 'environmental_practitioner','feasibility',UNHEX(:u))")->execute(['id'=>$p,'o'=>$o,'u'=>$u]);return[$o,$u,$p];}/** @param array<string,string>$h @param array<string,mixed>$b */private function json(string$m,string$p,array$h,array$b):Request{return Request::json($m,$p,$h+['Content-Type'=>'application/json'],json_encode((object)$b,JSON_THROW_ON_ERROR));}
}
